-- 3. Berita (5 artikel awal)
INSERT OR IGNORE INTO news (id, slug, title, category, date_label, published_at, location, cover_r2_key, excerpt, content_json, status) VALUES
  ('berita-01', 'youth-inspiration-camp-2026-perkuat-kepemimpinan-etoser', 'Youth Inspiration Camp 2026 Perkuat Karakter Kepemimpinan Etoser', 'Program', '18 Oktober 2026', '2026-10-18', 'Bogor', '/media/YIC_ETOS_ID_2026_001.webp', 'Ratusan Etoser dari 15 PTN mitra berkumpul dalam Youth Inspiration Camp untuk mengasah kepemimpinan kolaboratif dan rancangan proyek sosial daerah.', '["Youth Inspiration Camp (YIC) 2026 resmi digelar sebagai ruang konsolidasi nasional bagi para penerima manfaat Beasiswa ETOS ID dari berbagai Perguruan Tinggi Negeri mitra di Indonesia.","Selama tiga hari pelaksanaan, peserta mengikuti sesi penguatan spiritual, lokakarya kepemimpinan, serta perancangan inisiatif pemberdayaan yang menjawab persoalan nyata di daerah asal masing-masing.","Melalui forum ini, ETOS ID berharap lahir semakin banyak pemimpin muda tangguh yang tidak hanya unggul di ruang akademik, tetapi juga hadir memberi solusi di tengah masyarakat."]', 'published'),
  ('berita-02', 'etoser-raih-juara-karya-tulis-ilmiah-nasional', 'Tim Etoser Raih Juara Karya Tulis Ilmiah Nasional Bidang Inovasi Sosial', 'Prestasi', '5 Oktober 2026', '2026-10-05', 'Yogyakarta', '/media/YIC_ETOS_ID_2026_014.webp', 'Gagasan pemberdayaan ekonomi pesisir berbasis digital mengantarkan delegasi Etoser meraih podium utama di ajang kompetisi ilmiah tingkat nasional.', '["Delegasi mahasiswa penerima manfaat ETOS ID kembali menorehkan prestasi di kancah nasional melalui gagasan pemberdayaan ekonomi masyarakat pesisir yang aplikatif dan berkelanjutan.","Karya ilmiah tersebut lahir dari diskusi intensif di kelas Community of Interest, tempat para Etoser rutin mengasah kemampuan riset dan kepenulisan bersama mentor serta alumni.","Capaian ini menjadi bukti bahwa pendampingan terstruktur mampu mendorong mahasiswa daerah tampil percaya diri dan berdaya saing tinggi."]', 'published'),
  ('berita-03', 'monitoring-evaluasi-pembinaan-wilayah-sumatra-sulawesi', 'Monitoring & Evaluasi Pembinaan Wilayah Perkuat Sinergi Kampus Mitra', 'Aktivitas & Monev', '22 September 2026', '2026-09-22', 'Padang & Palu', '/media/YIC_ETOS_ID_2026_028.webp', 'Tim pengelola ETOS ID melaksanakan kunjungan monitoring dan evaluasi langsung guna memastikan kualitas pendampingan di berbagai wilayah mitra.', '["Sebagai bagian dari penjagaan mutu pembinaan 8 semester, tim ETOS ID menyelenggarakan rangkaian Monitoring dan Evaluasi (Monev) di sejumlah wilayah mitra kampus.","Agenda ini mencakup dialog perkembangan akademik Etoser, refleksi capaian proyek sosial, serta koordinasi bersama pihak kemahasiswaan kampus mitra setempat.","Hasil evaluasi menjadi pijakan penting untuk menyempurnakan kurikulum pembinaan agar semakin relevan dengan kebutuhan pengembangan SDM daerah."]', 'published'),
  ('berita-04', 'kuliah-tak-gentar-dampingi-pelajar-daerah-tembus-ptn', 'Gerakan Kuliah Tak Gentar Dampingi Ratusan Pelajar Daerah Tembus PTN', 'Program', '9 September 2026', '2026-09-09', 'Makassar', '/media/YIC_ETOS_ID_2026_039.webp', 'Etoser turun langsung membimbing siswa kelas 12 dari sekolah daerah lewat kelas motivasi, tryout, dan strategi seleksi masuk perguruan tinggi negeri.', '["Program Kuliah Tak Gentar (KTG) kembali membuka ruang pendampingan intensif bagi pelajar kelas 12 di berbagai wilayah mitra ETOS ID.","Para Etoser berperan langsung sebagai kakak mentor yang membagikan pengalaman kuliah, kiat menghadapi seleksi masuk PTN, serta informasi peluang beasiswa pendidikan tinggi.","Semangat kerelawanan ini diharapkan memutus batas akses informasi sehingga semakin banyak pelajar daerah berani melanjutkan pendidikan ke jenjang sarjana."]', 'published'),
  ('berita-05', 'career-project-bekali-etoser-tingkat-akhir-siap-berkarya', 'Career Project Bekali Etoser Tingkat Akhir Masuk Dunia Profesional', 'Aktivitas & Monev', '27 Agustus 2026', '2026-08-27', 'Medan', '/media/YIC_ETOS_ID_2026_043.webp', 'Melalui sesi career coaching dan Meet the Expert, Etoser tahun keempat menyiapkan langkah pascakampus bersama praktisi lintas industri.', '["Memasuki fase akhir masa studi, Etoser tingkat keempat mengikuti rangkaian Career Project yang berfokus pada kesiapan karier, penyusunan portofolio, dan simulasi wawancara profesional.","Hadir pula sejumlah alumni ETOS ID dari berbagai sektor yang berbagi pengalaman meniti karier sekaligus menjaga komitmen kontribusi sosial selepas lulus.","Pembekalan ini menjadi jembatan strategis menuju prosesi Lepas Juang dan kiprah nyata para alumni di tengah masyarakat."]', 'published');

-- 4. Testimoni Alumni (6 testimoni awal)
INSERT OR IGNORE INTO testimonials (id, name, campus, batch, photo_r2_key, testimonial, impact, sort_order, is_published) VALUES
  ('alumni-01', 'Nadia Rahmawati', 'UNAND', 'Angkatan 2020', '/media/YIC_ETOS_ID_2026_001.webp', 'Selama 4 tahun pembinaan di ETOS ID, saya tidak hanya terbantu secara finansial, tetapi juga ditempa lewat mentoring dan proyek sosial hingga berani pulang membangun ruang literasi di daerah asal.', 'Inisiator Rumah Baca Pemuda Sumatra Barat', 1, 1),
  ('alumni-02', 'Fajar Pratama', 'UNHAS', 'Angkatan 2019', '/media/YIC_ETOS_ID_2026_007.webp', 'Pembinaan di ETOS ID membuat saya paham bahwa kepemimpinan selalu dimulai dari kebermanfaatan terdekat. Jejaring alumni lintas kampus pun terus menjadi ruang kolaborasi hingga hari ini.', 'Penggerak Pendidikan Pesisir Sulawesi Selatan', 2, 1),
  ('alumni-03', 'Aulia Azzahra', 'UGM', 'Angkatan 2021', '/media/YIC_ETOS_ID_2026_008.webp', 'Career Project benar-benar menjembatani saya dari bangku kuliah menuju dunia profesional. Sesi career coaching membantu memetakan kekuatan diri dan menyiapkan portofolio sejak dini.', 'Analis Riset Pembangunan Daerah', 3, 1),
  ('alumni-04', 'Rizky Ramadhan', 'USU', 'Angkatan 2018', '/media/YIC_ETOS_ID_2026_011.webp', 'Community of Interest menjadi ruang aman untuk bereksperimen, belajar dari kegagalan, hingga akhirnya mampu berkarya dan membawa inovasi sosial bersama rekan-rekan daerah.', 'Co-Founder Inisiatif Inovasi Sosial Medan', 4, 1),
  ('alumni-05', 'Siti Maulida', 'UNMUL', 'Angkatan 2019', '/media/YIC_ETOS_ID_2026_014.webp', 'Lingkungan yang saling menguatkan membuat saya tumbuh tangguh meski jauh dari keluarga. Nilai integritas dan kerelawanan selama pembinaan masih terus saya pegang dalam karier saat ini.', 'Pendamping Pemberdayaan UMKM Kalimantan Timur', 5, 1),
  ('alumni-06', 'Hendra Saputra', 'UNPATTI', 'Angkatan 2020', '/media/YIC_ETOS_ID_2026_028.webp', 'Bertemu dan bertumbuh bersama pemuda dari berbagai PTN mitra membuka cakrawala bahwa mahasiswa dari timur Indonesia punya ruang kontribusi yang sama besar bagi kemajuan bangsa.', 'Penggerak Kelas Inspirasi Pelajar Maluku', 6, 1);

